/// <reference lib="es2022" />
/**
 * Bun SQLite client whose raw writes report affected rows.
 *
 * @since 1.0.0
 */

import { Database } from "bun:sqlite"

interface Options {
  readonly filename: string
}

const make = (options: Options): Database => new Database(options.filename)

/**
 * The file a client opens.
 *
 * @category constructors
 * @since 1.0.0
 */
export const filename = (options: Options): string => make(options).filename
